fn row(profile:&Path)->Result<(i64,String)> {let db=rusqlite::Connection::open(profile.join("sarv.sqlite3"))?;Ok(db.query_row("SELECT generation,payload FROM state WHERE id=1",[],|r|Ok((r.get(0)?,r.get(1)?)))?)}
fn c(state:&State,source:&str,key:&str)->Value {let o=&state.accounting.core.openings[0].command;json!({"company_id":o.company_id,"period_id":o.period_id,"setup_id":o.setup_id,"date":"2026-04-04","source_id":source,"source_revision":1,"request_key":key,"actor":"Independent financial fault reviewer","reason":"Literal one-piece20IRR fulfillment after final interleaved fixture"})}
