 let mut st=Store::open(path)?;st.change(|s|{*s=state.clone();Ok(())})?;
 let order:SalesCommand=serde_json::from_value(json!({"Order":{"context":c(state,"fault-order","fault-order-key"),"customer_id":"party-a","reference":"FAULT-SO","document_date":"2026-04-04","lines":[{"id":"fault-order-line","item_id":"item-a","warehouse_id":"w1","unit_id":"piece","quantity_thousandths":1000,"unit_price":20,"line_discount":0,"price_reference":"Independent literal20IRR","price_date":"2026-04-04","override_reason":null}],"document_discount":0,"supplied_total":20,"quotation":null}}))?;
